typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Triangulation_vertex_base_2<K> Vb;
typedef CGAL::Triangulation_face_base_2<K> Fb;
typedef CGAL::Triangulation_data_structure_2<Vb, Fb> TDS;
typedef CGAL::Delaunay_triangulation_2<K, TDS> Triangulation2;

Triangulation2 dt;
for (const cg3::Point2d& p : points) {
    dt.insert(K::Point_2(p.x(), p.y()));
}

std::vector<std::array<cg3::Point2d, 3> > triangles;
for (Triangulation2::Finite_faces_iterator fit = dt.finite_faces_begin();
     fit != dt.finite_faces_end(); ++fit) {
    std::array<cg3::Point2d, 3> t;
    t[0] = cg3::Point2d(fit->vertex(0)->point().x(), fit->vertex(0)->point().y());
    t[1] = cg3::Point2d(fit->vertex(1)->point().x(), fit->vertex(1)->point().y());
    t[2] = cg3::Point2d(fit->vertex(2)->point().x(), fit->vertex(2)->point().y());
    triangles.push_back(t);
}
return triangles;

